local MyClubService, SharedFUTEnums, TableUtil, EventManager = ...local EVENT_TYPES = EventManager.FE.FIFA.EventTypeslocal InventoryModel = {}InventoryModel.LISTENER_TYPES = MyClubService.FE.UXService.StatisticsListenerTypeInventoryModel.SEARCH_TYPES = SharedFUTEnums.MyClub.eSearchTypeInventoryModel.CATEGORIES = SharedFUTEnums.MyClub.eCategoryInventoryModel.SEARCH_FILTERS = {  SEARCH_TYPE = "searchType",  LEVEL = "level",  ROLE = "searchStaffRoles",  POSITION = "position",  CLUB_TYPE = "clubType",  CONSUMABLE_TYPE = "consumableType",  FORMATION = "formation",  NATIONALITY = "nationality",  LEAGUE = "league",  CLUB = "club"}InventoryModel.COLLECTIONS_ALL = 1function InventoryModel:new(init)  print("[InventoryModel]: new()")  local o = init or {}  setmetatable(o, self)  self.__index = self  o.services = {    SquadManagementService = o.api("SquadMgtService"),    TacticsService = o.api("TacticsService"),    CountryService = o.api("CountryService"),    TeamService = o.api("TeamService"),    ItemsService = o.api("ItemsService"),    MyClubService = o.api("MyClubService"),    EventManagerService = o.api("EventManagerService")  }  o.eventHandlerID = o.services.EventManagerService.RegisterHandler(function(...)    o:_handleEvent(...)  end  )  o.searchId = -1  return oendfunction InventoryModel:showBlockingLoad(show)  if show == nil or show == true then    self.nav.Event(nil, "evt_show_blocking_load")  else    self.nav.Event(nil, "evt_hide_blocking_load")  endendfunction InventoryModel:generateSearchParams(startIndex, numResults, itemType, itemLevel, itemPosition, itemFormation, itemNationality, itemLeague, itemClub)  print("[InventoryModel]: generateSearchParams()")  local params = {    START = startIndex or 0,    NUMBER_RESULTS = numResults or 9,    SEARCH_TYPE = itemType or 1,    POSITION = itemPosition or -1,    FORMATION = itemFormation or -1,    NATIONALITY = itemNationality or 0,    LEAGUE = itemLeague or 0,    CLUB = itemClub or 0  }  if not EA_FINAL then    TableUtil.print(params)  end  return paramsendfunction InventoryModel:getSearchFilters(leagueID)  print("[InventoryModel]: getSearchFilters()")  local tmpFilters = self.services.MyClubService.GetAllSearchOptions()  local filters = {}  filters[InventoryModel.SEARCH_FILTERS.SEARCH_TYPE] = tmpFilters[InventoryModel.SEARCH_FILTERS.SEARCH_TYPE].data  filters[InventoryModel.SEARCH_FILTERS.LEVEL] = tmpFilters[InventoryModel.SEARCH_FILTERS.LEVEL].data  filters[InventoryModel.SEARCH_FILTERS.ROLE] = tmpFilters[InventoryModel.SEARCH_FILTERS.ROLE].data  filters[InventoryModel.SEARCH_FILTERS.POSITION] = tmpFilters[InventoryModel.SEARCH_FILTERS.POSITION].data  filters[InventoryModel.SEARCH_FILTERS.CLUB_TYPE] = tmpFilters[InventoryModel.SEARCH_FILTERS.CLUB_TYPE].data  filters[InventoryModel.SEARCH_FILTERS.CONSUMABLE_TYPE] = tmpFilters[InventoryModel.SEARCH_FILTERS.CONSUMABLE_TYPE].data  filters[InventoryModel.SEARCH_FILTERS.FORMATION] = {    label = self.loc.LocalizeString("LTXT_SB_FORMATION"),    type = "FORMATION",    index = 0,    data = self:getFormationFilters()  }  filters[InventoryModel.SEARCH_FILTERS.NATIONALITY] = {    label = self.loc.LocalizeString("LTXT_SB_NATIONALITY"),    type = "NATIONALITY",    index = 0,    data = self:getNationalityFilters()  }  filters[InventoryModel.SEARCH_FILTERS.LEAGUE] = {    label = self.loc.LocalizeString("LTXT_SB_LEAGUE"),    type = "LEAGUE",    index = 0,    data = self:getLeagueFilters()  }  filters[InventoryModel.SEARCH_FILTERS.CLUB] = {    label = self.loc.LocalizeString("LTXT_SB_CLUB"),    type = "CLUB",    index = 0,    data = self:getClubFilters(leagueID)  }  if not EA_FINAL then    do      for i, i in pairs(filters) do        TableUtil.print(i)      end    end  end  return filtersendfunction InventoryModel:getFormationFilters()  local formationIDs = self.services.SquadManagementService.GetAvailableFormationIDs(true)  local formationNames = self.services.TacticsService.GetAllFormationNames(true)  local formations = {}  local nFormations = table.getn(formationIDs)  table.insert(formations, {    name = self.loc.LocalizeString("LTXT_CMN_ANY"),    value = -1  })  do    do      for i = 1, nFormations do        table.insert(formations, {          name = formationNames[i].name,          value = formationIDs[i]        })      end    end  end  return formationsendfunction InventoryModel:getNationalityFilters()  local nationalityIDs = self.services.CountryService.GetIDs(true)  local nationalities = {}  local nNationalities = table.getn(nationalityIDs)  table.insert(nationalities, {    name = self.loc.LocalizeString("LTXT_CMN_ANY"),    value = 0  })  do    do      for i = 1, nNationalities do        local nationalityID = nationalityIDs[i].id        table.insert(nationalities, {          name = nationalityIDs[i].name,          value = nationalityID        })      end    end  end  return nationalitiesendfunction InventoryModel:getLeagueFilters()  local categories = self.services.MyClubService.GetCategoriesForCollection(InventoryModel.COLLECTIONS_ALL)  local leagues = {}  table.insert(leagues, {    name = self.loc.LocalizeString("LTXT_CMN_ANY"),    id = 0,    value = 0  })  do    do      for i, i in ipairs(categories) do        if i.IS_TEAM_CATEGORY == true then          local leagueIDs = self.services.MyClubService.GetLeagueIDsForCategoryInCollectionWithoutInternational(InventoryModel.COLLECTIONS_ALL, i.CATEGORY_ID)          do            for i, i in ipairs(leagueIDs) do              local leagueID = i.LEAGUEID              table.insert(leagues, {                name = self.loc.LocalizeString("LeagueName_Abbr15_" .. leagueID),                id = leagueID,                value = leagueID              })            end          end        end      end    end  end  return leaguesendfunction InventoryModel:getClubFilters(leagueID)  local clubs = {}  table.insert(clubs, {    name = self.loc.LocalizeString("LTXT_CMN_ANY"),    id = 0,    value = 0  })  if leagueID ~= nil and leagueID ~= 0 then    local teams = self.services.TeamService.GetFUTTeams(leagueID)    do      for i, i in ipairs(teams) do        table.insert(clubs, {          name = i.name,          id = i.id,          value = i.id        })      end    end  end  return clubsendfunction InventoryModel:requestInventoryStatistics(onCompleteCallback, onFailCallback)  print("[InventoryModel]: requestInventoryStatistics()")  self.services.MyClubService.RequestStatistics()  self.onRequestInventoryStatisticsCompleteCallback = onCompleteCallback  self.onRequestInventoryStatisticsFailCallback = onFailCallbackendfunction InventoryModel:searchInventory(searchType, searchParams, startIndex, numResults, onCompleteCallback, onFailCallback)  print("[InventoryModel]: searchInventory() - ClubSearch")  TableUtil.print(searchParams)  self:showBlockingLoad(true)  searchParams.SEARCH_TYPE = searchType or self.SEARCH_TYPES.FUT_CST_ALL  searchParams.START = startIndex or 0  searchParams.NUMBER_RESULTS = numResults or 9  searchParams.CURRENT_SEARCH_ID = self.searchId  self.onSearchInventoryCompleteCallback = onCompleteCallback  self.onSearchInventoryFailCallback = onFailCallback  self.searchId = self.services.ItemsService.ClubSearch(searchParams)endfunction InventoryModel:_onRequestInventoryStatisticsComplete(response, phase)  print("[InventoryModel]: _onRequestInventoryStatisticsComplete(" .. phase .. ")")  if not EA_FINAL then    TableUtil.print(response)  end  if response.status == "ERROR" then    if self.onRequestInventoryStatisticsFailCallback ~= nil then      self.onRequestInventoryStatisticsFailCallback()    end    self.statistics = nil    self.onRequestInventoryStatisticsCompleteCallback = nil    self.onRequestInventoryStatisticsFailCallback = nil  elseif response.status == "OK" then    if phase == 1 then      local categories = self.services.MyClubService.GetCategoriesForCollection(InventoryModel.COLLECTIONS_ALL)      local tmpStatistics = self.services.MyClubService.GetStatistics(categories)      self.statistics = {}      self.statistics.PLAYERS_EMPLOYED = 0      self.statistics.KITS_AVAILABLE = 0      self.statistics.BADGES_AVAILABLE = 0      self.statistics.RARE_PLAYERS_EMPLOYED = 0      self.statistics.STADIA_OWNED = 0      self.statistics.BALLS_EARNED = 0      do        do          for i, i in ipairs(tmpStatistics) do            if categories[i].CATEGORY_ID == InventoryModel.CATEGORIES.ENGLAND_CATEGORY or categories[i].CATEGORY_ID == InventoryModel.CATEGORIES.FRANCE_CATEGORY or categories[i].CATEGORY_ID == InventoryModel.CATEGORIES.GERMANY_CATEGORY or categories[i].CATEGORY_ID == InventoryModel.CATEGORIES.ITALY_CATEGORY or categories[i].CATEGORY_ID == InventoryModel.CATEGORIES.SPAIN_CATEGORY or categories[i].CATEGORY_ID == InventoryModel.CATEGORIES.REST_EUROPE_CATEGORY or categories[i].CATEGORY_ID == InventoryModel.CATEGORIES.REST_WORLD_CATEGORY then              self.statistics.PLAYERS_EMPLOYED = self.statistics.PLAYERS_EMPLOYED + i.PLAYERS_EMPLOYED              self.statistics.KITS_AVAILABLE = self.statistics.KITS_AVAILABLE + i.KITS_AVAILABLE              self.statistics.BADGES_AVAILABLE = self.statistics.BADGES_AVAILABLE + i.BADGES_AVAILABLE              self.statistics.RARE_PLAYERS_EMPLOYED = self.statistics.RARE_PLAYERS_EMPLOYED + i.RARE_PLAYERS_EMPLOYED            end            if categories[i].CATEGORY_ID == InventoryModel.CATEGORIES.STADIUMS_CATEGORY then              self.statistics.STADIA_OWNED = self.statistics.STADIA_OWNED + i.STADIA_OWNED            end            if categories[i].CATEGORY_ID == InventoryModel.CATEGORIES.BALLS_CATEGORY then              self.statistics.BALLS_EARNED = self.statistics.BALLS_EARNED + i.BALLS_EARNED            end          end        end      end      self.services.MyClubService.RequestStatisticsForNewCards()    else      local tmpStatistics = self.services.MyClubService.GetStatisticsForNewCards()      do        do          for i, i in pairs(tmpStatistics) do            self.statistics[i] = i          end        end      end      if not EA_FINAL then        TableUtil.print(self.statistics)      end      if self.onRequestInventoryStatisticsCompleteCallback ~= nil then        self.onRequestInventoryStatisticsCompleteCallback(self.statistics)      end      self.statistics = nil      self.onRequestInventoryStatisticsCompleteCallback = nil      self.onRequestInventoryStatisticsFailCallback = nil    end  endendfunction InventoryModel:_onSearchInventoryComplete(response)  print("[InventoryModel]: _onSearchInventoryComplete()")  if not EA_FINAL then    TableUtil.print(response)  end  if self.searchId == response.searchId then    self:showBlockingLoad(false)    self.searchId = -1    if response.status == "OK" then      local results = response.data      local lastIndex = response.lastIndex      if self.onSearchInventoryCompleteCallback ~= nil then        self.onSearchInventoryCompleteCallback(results, lastIndex)      end    elseif self.onSearchInventoryFailCallback ~= nil then      self.onSearchInventoryFailCallback()    end    self.onSearchInventoryCompleteCallback = nil    self.onSearchInventoryFailCallback = nil  else    print("InventoryModel:_onSearchInventoryComplete ignoring id = " .. tostring(response.searchId))  endendfunction InventoryModel:_handleEvent(eventType, data)  if eventType == EVENT_TYPES.ClubSearch then    self:_onSearchInventoryComplete(data)  elseif eventType == EVENT_TYPES.RequestStatistics then    self:_onRequestInventoryStatisticsComplete(data, 1)  elseif eventType == EVENT_TYPES.RequestStatisticsForNewCards then    self:_onRequestInventoryStatisticsComplete(data, 2)  endendfunction InventoryModel:finalize()  print("[InventoryModel]: finalize")  self:showBlockingLoad(false)  self.statistics = nil  self.onRequestInventoryStatisticsCompleteCallback = nil  self.onRequestInventoryStatisticsFailCallback = nil  self.onSearchInventoryCompleteCallback = nil  self.onSearchInventoryFailCallback = nil  self.services.EventManagerService.UnregisterHandler(self.eventHandlerID)endreturn InventoryModel